INSERT INTO visitas (id, notificacion_id, migrated_from_glide, resultado, observaciones, ubicacion_lat, ubicacion_lng, foto_url, fecha) VALUES ('0998995b-3813-4e50-a312-774c4f962cdd', '8d7274d3-348f-41f4-8cc7-02458ede2a78', 1, 'No Atiende', 'Vecino me informan que el destinatario hace muchos años vivió vendió toda la propiedad y en lo que era la propiedad del mismo existen construida aproximadamente siete viviendas por lo que procedo a dejar en la casa que menos complicación tuve Por cuánto es un barrio sumamente peligroso y hay la presencia de varios masculinos en estado de ebriedad y drogados este dando vuelta amenazándome por lo que procedo a dejar en el primer lugar que forma parte del inmueble donde vivía antes la destinatario', NULL, NULL, 'https://storage.googleapis.com/glide-prod.appspot.com/uploads-v2/1hfcSKizDmCWbiikjxDb/pub/kIKQq7VIRcebWgaMk18Z.jpg', '2025-11-05 17:08:52');
