INSERT INTO visitas (id, notificacion_id, migrated_from_glide, resultado, observaciones, ubicacion_lat, ubicacion_lng, foto_url, fecha) VALUES ('d8725b50-78a3-4736-9343-3376304a795c', '8d7274d3-348f-41f4-8cc7-02458ede2a78', 1, 'No Atiende', NULL, NULL, NULL, NULL, '2025-11-05 17:23:37');
INSERT INTO visitas (id, notificacion_id, migrated_from_glide, resultado, observaciones, ubicacion_lat, ubicacion_lng, foto_url, fecha) VALUES ('4e000c02-a981-4ac6-b3a6-b99ca3ef3ef3', '8d7274d3-348f-41f4-8cc7-02458ede2a78', 1, 'No Atiende', 'Por averiguaciones recabadas en la zona los vecinos me informan que el destinatario hace más de 7 años no vive en el lugar y que la propiedad donde vivía La vendió actualmente existen ocho vivienda construida en lo que era la propiedad que pertenecía al destinatario por lo que ningunas de las personas que ocupaban las viviendas me quiso recibir debido a ello y tratándose de una zona sumamente peligrosa habida cuenta que había la existencia de varios masculinos en estado de ebriedad y drogados dando vuelta y amenazándome es que procedo a dejar copia por debajo de la puerta en una de las viviendas que fue construida en la propiedad que pertenecía al destinatario así también me informa que el mismo se encontraría viviendo en la provincia de Mendoza', NULL, NULL, NULL, '2025-11-05 17:28:08');
